import { Elysia, t } from "elysia";

const models = {
  Body: t.Object({ name: t.String() }),
  Params: t.Object({ id: t.String() }),
  Response: t.Object({ id: t.String(), name: t.String() }),
};

new Elysia()
  .model(models)
  .post("/literal/:id", {
    body: t.Object({ name: t.String() }),
    params: t.Object({ id: t.String() }),
    response: t.Object({ id: t.String(), name: t.String() }),
  }, ({ body, params, request }) => ({ id: params.id, name: `${body.name}:${request.method}` }))
  .post("/reference/:id", {
    body: "Body",
    params: "Params",
    response: "Response",
  }, ({ body, params, request }) => ({ id: params.id, name: `${body.name}:${request.method}` }));

const authorization = new Elysia().macro({
  permission: (permission: string) => ({
    derive: async ({ request }) => ({ actor: `${permission}:${request.method}` }),
  }),
});

new Elysia()
  .use(authorization)
  .model(models)
  .post("/macro/:id", {
    body: "Body",
    params: "Params",
    permission: "write",
    response: "Response",
  }, ({ actor, body, params, request }) => ({
    id: params.id,
    name: `${actor}:${body.name}:${request.method}`,
  }));

